function categoryById(id){return remoteCategories.find(category=>category.id===id);}
function rootCategoryId(id){let current=categoryById(id),guard=0;while(current?.categoria_padre_id&&guard++<20)current=categoryById(current.categoria_padre_id);return current?.id||id;}
