function normalizedColor(value){return String(value||'').trim();}
function normalizeSearch(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase().replace(/[^a-z0-9]+/g,' ').trim();}
function editDistance(a,b){const rows=Array.from({length:a.length+1},(_,i)=>[i]);for(let j=0;j<=b.length;j++)rows[0][j]=j;for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++)rows[i][j]=a[i-1]===b[j-1]?rows[i-1][j-1]:Math.min(rows[i-1][j]+1,rows[i][j-1]+1,rows[i-1][j-1]+1);return rows[a.length][b.length];}
function searchMatches(product,term){const words=normalizeSearch(term).split(' ').filter(Boolean);if(!words.length)return true;const text=normalizeSearch([product.name,product.category,product.brand?.nombre,product.description,product.color].join(' ')),tokens=text.split(' ');return words.every(word=>text.includes(word)||tokens.some(token=>word.length>3&&Math.abs(token.length-word.length)<=1&&editDistance(token,word)<=1));}
function productMatches(product,state=filterState,omit=''){const categoryId=rootCategoryId(product.categoryId),price=Number(product.price)||0,term=query.trim();if(omit!=='categoryId'&&state.categoryId&&categoryId!==state.categoryId)return false;if(omit!=='subcategories'&&state.subcategories.size&&!state.subcategories.has(product.categoryId))return false;if(omit!=='brands'&&state.brands.size&&!state.brands.has(product.brandId||''))return false;if(omit!=='colors'&&state.colors.size&&!state.colors.has(normalizedColor(product.color)))return false;if(omit!=='pieces'&&state.pieces.size&&!state.pieces.has(String(product.pieces??'')))return false;if(omit!=='featured'&&state.featured&&!product.featured)return false;if(omit!=='price'&&state.minPrice!==null&&price<state.minPrice)return false;if(omit!=='price'&&state.maxPrice!==null&&price>state.maxPrice)return false;return !term||searchMatches(product,term);}
