function paginationItems(totalPages){if(totalPages<=7)return Array.from({length:totalPages},(_,index)=>index+1);const pages=new Set([1,totalPages,currentPage-1,currentPage,currentPage+1]);const ordered=[...pages].filter(page=>page>=1&&page<=totalPages).sort((a,b)=>a-b),items=[];ordered.forEach((page,index)=>{if(index&&page-ordered[index-1]>1)items.push('…');items.push(page)});return items;}
function renderPagination(totalPages){const markup=totalPages<=1?'':`<button type="button" class="pagination-arrow" data-page="${currentPage-1}" ${currentPage===1?'disabled':''} aria-label="Página anterior">‹</button>${paginationItems(totalPages).map(item=>item==='…'?'<span class="pagination-ellipsis">…</span>':`<button type="button" class="pagination-page ${item===currentPage?'is-current':''}" data-page="${item}" ${item===currentPage?'aria-current="page"':''}>${item}</button>`).join('')}<button type="button" class="pagination-arrow" data-page="${currentPage+1}" ${currentPage===totalPages?'disabled':''} aria-label="Página siguiente">›</button>`;document.querySelectorAll('.catalog-pagination').forEach(nav=>nav.innerHTML=markup);}
function renderProducts(){if(!hasCatalogPage)return;const list=filtered(),totalPages=Math.max(1,Math.ceil(list.length/PRODUCTS_PER_PAGE));currentPage=Math.min(Math.max(1,currentPage),totalPages);const pageProducts=list.slice((currentPage-1)*PRODUCTS_PER_PAGE,currentPage*PRODUCTS_PER_PAGE),label=`${list.length} producto${list.length===1?'':'s'}`;document.querySelector('#productGrid').innerHTML=list.length?pageProducts.map(card).join(''):'<p class="catalog-empty">No encontramos productos con estos filtros. Prueba a eliminar alguno.</p>';const count=document.querySelector('#filterResultCount'),mobileCount=document.querySelector('#mobileProductTotal'),mobileSort=document.querySelector('#mobileSort');if(count)count.textContent=label;if(mobileCount)mobileCount.textContent=label;if(mobileSort)mobileSort.value=filterState.sort;renderPagination(list.length?totalPages:0);bindAddToCartButtons();bindFavoriteButtons();}
function facetValues(key){const base=products.filter(product=>productMatches(product,filterState,key));const values=new Map();const add=(value,label)=>{if(value===null||value===undefined||value==='')return;const item=values.get(String(value))||{value:String(value),label,count:0};item.count++;values.set(String(value),item)};base.forEach(product=>{if(key==='categoryId')add(rootCategoryId(product.categoryId),categoryName(rootCategoryId(product.categoryId)));if(key==='subcategories'&&filterState.categoryId&&rootCategoryId(product.categoryId)===filterState.categoryId&&product.categoryId!==filterState.categoryId)add(product.categoryId,categoryName(product.categoryId));if(key==='brands'&&product.brandId)add(product.brandId,product.brand?.nombre||'Sin marca');if(key==='colors')add(normalizedColor(product.color),normalizedColor(product.color));if(key==='pieces'&&Number.isFinite(Number(product.pieces))&&Number(product.pieces)>0)add(String(product.pieces),`${product.pieces} pieza${Number(product.pieces)===1?'':'s'}`)});return [...values.values()].sort((a,b)=>a.label.localeCompare(b.label,'es'));}
function accordion(title,body,{open=false,hidden=false}={}){return hidden?'':`<details class="filter-accordion" ${open?'open':''}><summary>${title}<span aria-hidden="true">⌄</span></summary>${body}</details>`;}
