function renderActiveFilterChips(){const host=document.querySelector('#activeFilterChips');if(!host)return;const chips=[];if(filterState.categoryId)chips.push(['categoryId',filterState.categoryId,categoryName(filterState.categoryId)]);[['subcategories',filterState.subcategories],['brands',filterState.brands],['colors',filterState.colors],['pieces',filterState.pieces]].forEach(([key,values])=>values.forEach(value=>chips.push([key,value,key==='subcategories'?categoryName(value):key==='brands'?(remoteBrands.find(brand=>brand.id===value)?.nombre||'Marca'):key==='pieces'?`${value} piezas`:value])));if(filterState.minPrice!==null||filterState.maxPrice!==null)chips.push(['price','',`Precio ${filterState.minPrice!==null?money(filterState.minPrice):'mín.'} – ${filterState.maxPrice!==null?money(filterState.maxPrice):'máx.'}`]);host.innerHTML=chips.map(([key,value,label])=>`<button type="button" class="filter-chip" data-remove-filter="${key}" data-value="${escapeHtml(value)}">${escapeHtml(label)} ×</button>`).join('');}
function renderFilters(){if(!hasCatalogPage)return;const host=document.querySelector('#smartFilters');if(!host)return;const prices=products.map(product=>Number(product.price)).filter(Number.isFinite),min=Math.floor(Math.min(...prices,0)),max=Math.ceil(Math.max(...prices,0));const categoryOptions=facetValues('categoryId'),subcategoryOptions=facetValues('subcategories'),brandOptions=facetValues('brands'),colorOptions=facetValues('colors'),pieceOptions=facetValues('pieces');host.innerHTML=accordion('Ordenar por',`<div class="filter-options sort-options"><label class="filter-option"><input type="radio" name="sort" value="price-asc" ${filterState.sort==='price-asc'?'checked':''} data-smart-sort><span>Precio: menor a mayor</span></label><label class="filter-option"><input type="radio" name="sort" value="price-desc" ${filterState.sort==='price-desc'?'checked':''} data-smart-sort><span>Precio: mayor a menor</span></label></div>`,{open:true})+accordion('Categoría',selectableOptions('categoryId',categoryOptions,{multiple:false}),{open:true})+accordion('Subcategorías',selectableOptions('subcategories',subcategoryOptions),{hidden:!filterState.categoryId||!subcategoryOptions.length})+accordion('Marca',selectableOptions('brands',brandOptions),{hidden:!brandOptions.length})+accordion('Color',selectableOptions('colors',colorOptions),{hidden:!colorOptions.length})+accordion('Número de piezas',selectableOptions('pieces',pieceOptions),{hidden:!pieceOptions.length})+accordion('Precio',`<p class="filter-hint">Rango disponible: ${money(min)} – ${money(max)}</p><div class="price-inputs"><label>Desde<input type="number" inputmode="decimal" min="${min}" max="${max}" value="${filterState.minPrice??''}" placeholder="${min}" data-price-bound="min"></label><label>Hasta<input type="number" inputmode="decimal" min="${min}" max="${max}" value="${filterState.maxPrice??''}" placeholder="${max}" data-price-bound="max"></label></div>`);renderActiveFilterChips();}
function refreshCatalog(resetPage=true){if(resetPage)currentPage=1;renderCatalogDiscovery();renderFilters();renderProducts();renderCategoryDescription();}
function renderCatalogDiscovery(){
  if(!hasCatalogPage)return;
  const section=document.querySelector('#catalogDiscoverySection'),title=document.querySelector('#catalogDiscoveryTitle'),host=document.querySelector('#catalogDiscovery');
  if(!section||!title||!host)return;
  const childrenOf=id=>remoteCategories.filter(category=>category.categoria_padre_id===id);
  const imageFor=category=>category?.imagen_url?`<img src="${escapeHtml(safeImageUrl(category.imagen_url))}" alt="" loading="lazy">`:`<span class="catalog-discovery-monogram">${escapeHtml((category?.icono||category?.nombre||'?').slice(0,1).toUpperCase())}</span>`;
  const hasProduct=(predicate,omit)=>products.some(product=>predicate(product)&&productMatches(product,filterState,omit));
  let mode='category',items=[],label='Explora por categoría';
  if(!filterState.categoryId){
    items=remoteCategories.filter(category=>!category.categoria_padre_id&&hasProduct(product=>rootCategoryId(product.categoryId)===category.id,'categoryId'));
  }else{
    const children=childrenOf(filterState.categoryId);
    if(children.length&&!filterState.subcategories.size){
      mode='subcategory';
      items=children.filter(category=>hasProduct(product=>product.categoryId===category.id,'subcategories'));
      label=`Subcategorías de ${categoryName(filterState.categoryId)}`;
    }else{
      mode='brand';
      items=facetValues('brands').map(option=>remoteBrands.find(brand=>brand.id===option.value)).filter(Boolean);
      label='Marcas disponibles';
    }
  }
  if(!items.length){section.hidden=true;return;}
  section.hidden=false;title.textContent=label;
  host.innerHTML=items.map(item=>{const selected=mode==='brand'?filterState.brands.has(item.id):mode==='subcategory'?filterState.subcategories.has(item.id):filterState.categoryId===item.id;const kind=mode==='brand'?'brand':mode;const visual=mode==='brand'?(item.logo_url?`<img src="${escapeHtml(safeImageUrl(item.logo_url))}" alt="" loading="lazy">`:`<span class="catalog-discovery-monogram">${escapeHtml(brandInitial(item.nombre))}</span>`):imageFor(item);return `<button type="button" class="catalog-discovery-card ${selected?'is-selected':''}" data-catalog-discovery="${kind}" data-id="${item.id}" aria-pressed="${selected}"><span class="catalog-discovery-image">${visual}</span><strong>${escapeHtml(item.nombre)}</strong></button>`;}).join('');
  if(!host.dataset.bound){host.dataset.bound='true';host.addEventListener('click',event=>{const button=event.target.closest('[data-catalog-discovery]');if(!button)return;const kind=button.dataset.catalogDiscovery,id=button.dataset.id;if(kind==='category'){filterState.categoryId=id;filterState.subcategories.clear();filterState.brands.clear();activeCategory=categoryName(id);}else if(kind==='subcategory'){filterState.subcategories.has(id)?filterState.subcategories.delete(id):filterState.subcategories.add(id);filterState.brands.clear();}else if(kind==='brand'){filterState.brands.has(id)?filterState.brands.delete(id):filterState.brands.add(id);}refreshCatalog();});}
  setupCatalogDiscoveryCarousel();
}
function setupCatalogDiscoveryCarousel(){
  const track=document.querySelector('#catalogDiscovery'),previous=document.querySelector('#catalogDiscoveryPrevious'),next=document.querySelector('#catalogDiscoveryNext');
  if(!track||!previous||!next)return;
  const update=()=>{const overflow=track.scrollWidth-track.clientWidth>4;previous.hidden=!overflow;next.hidden=!overflow;previous.disabled=track.scrollLeft<=2;next.disabled=!overflow||track.scrollLeft+track.clientWidth>=track.scrollWidth-2;};
  if(!track.dataset.carouselBound){
    track.dataset.carouselBound='true';
    previous.addEventListener('click',()=>track.scrollBy({left:-Math.max(180,track.clientWidth*.72),behavior:'smooth'}));
    next.addEventListener('click',()=>track.scrollBy({left:Math.max(180,track.clientWidth*.72),behavior:'smooth'}));
    track.addEventListener('scroll',update,{passive:true});
    if('ResizeObserver' in window)new ResizeObserver(update).observe(track);
  }
  requestAnimationFrame(update);
}
function setCategoryByName(name){const category=remoteCategories.find(item=>item.nombre===name);filterState.categoryId=category?rootCategoryId(category.id):null;filterState.subcategories.clear();activeCategory=name||'Todos';refreshCatalog();}
function selectCategoryFromHeader(name){const category=remoteCategories.find(item=>item.nombre===name);if(!category){filterState.categoryId=null;filterState.subcategories.clear();activeCategory='Todos';refreshCatalog();return;}const rootId=rootCategoryId(category.id);filterState.categoryId=rootId;filterState.subcategories.clear();if(category.id!==rootId)filterState.subcategories.add(category.id);activeCategory=categoryName(rootId);refreshCatalog();}
function escapeHtml(value=''){const element=document.createElement('span');element.textContent=value;return element.innerHTML;}
function safeImageUrl(value){const source=String(value||'').trim();return /^(https?:\/\/|data:image\/svg\+xml,)/i.test(source)?source:PRODUCT_IMAGE_FALLBACK;}
function renderCategoryNavigation(){const nav=document.querySelector('#categoryNav');if(!remoteCategories.length){nav.innerHTML='<span class="nav-loading">No hay categorías disponibles.</span>';return;}const childrenOf=id=>remoteCategories.filter(category=>category.categoria_padre_id===id);const roots=remoteCategories.filter(category=>!category.categoria_padre_id);const categoryHref=category=>hasCatalogPage?'#catalogo':`catalogo.html?categoria=${encodeURIComponent(category.slug)}`;const link=category=>`<a href="${categoryHref(category)}" data-category="${escapeHtml(category.nombre)}" data-category-id="${category.id}">${category.icono?`<span aria-hidden="true">${escapeHtml(category.icono)}</span> `:''}${escapeHtml(category.nombre)}</a>`;const allHref=hasCatalogPage?'#catalogo':'catalogo.html';nav.innerHTML=`<a href="${allHref}" data-category="Todos">Todo el catálogo</a>${roots.map(parent=>{const children=childrenOf(parent.id);if(!children.length)return link(parent);const panelId=`subcategorias-${parent.id}`,viewAll=`<a class="subnav-view-all" href="${categoryHref(parent)}" data-category="${escapeHtml(parent.nombre)}" data-category-id="${parent.id}">Ver todo</a>`;return `<div class="nav-dropdown"><a class="nav-parent-link" href="${categoryHref(parent)}" data-category="${escapeHtml(parent.nombre)}" data-category-id="${parent.id}">${escapeHtml(parent.nombre)}</a><button class="nav-parent" type="button" aria-expanded="false" aria-controls="${panelId}" aria-label="Mostrar subcategorías de ${escapeHtml(parent.nombre)}" data-subnav-toggle><span>${escapeHtml(parent.nombre)}</span><span class="subnav-toggle" aria-hidden="true" data-subnav-icon>⌄</span></button><div class="subnav" id="${panelId}">${viewAll}${children.map(link).join('')}</div></div>`}).join('')}<a href="${hasCatalogPage?'index.html#destacados':'#destacados'}" class="sale-link">Destacados</a>`;bindSubcategoryToggles();}
function bindSubcategoryToggles(){document.querySelectorAll('[data-subnav-toggle]').forEach(button=>button.addEventListener('click',()=>{const dropdown=button.closest('.nav-dropdown'),willOpen=!dropdown.classList.contains('open');dropdown.classList.toggle('open',willOpen);button.setAttribute('aria-expanded',String(willOpen));button.setAttribute('aria-label',`${willOpen?'Ocultar':'Mostrar'} subcategorías`);button.querySelector('[data-subnav-icon]').textContent=willOpen?'⌃':'⌄';}));}
async function loadCategoriesFromSupabase(){if(!supabaseClient)return;const {data,error}=await supabaseClient.from('categorias').select('id,nombre,slug,categoria_padre_id,imagen_url,orden,icono').eq('activo',true).eq('visible_ecommerce',true).order('orden',{ascending:true,nullsFirst:false}).order('nombre',{ascending:true});if(error){console.error('No se pudieron cargar las categorías de Supabase:',error.message);document.querySelector('#categoryNav').innerHTML='<span class="nav-loading">Las categorías estarán disponibles pronto.</span>';return;}remoteCategories=data||[];categories=['Todos',...remoteCategories.map(category=>category.nombre)];const requestedSlug=pageParams.get('categoria');const requestedCategory=remoteCategories.find(category=>category.slug===requestedSlug);if(requestedCategory)activeCategory=requestedCategory.nombre;if(activeCategory!=='Todos'&&!categories.includes(activeCategory))activeCategory='Todos';renderCategoryNavigation();renderCategoryCarousel();renderCatalogDiscovery();renderFilters();renderProducts();}
