function toggleCart(open){document.querySelector('#cartDrawer').classList.toggle('open',open);document.querySelector('#overlay').classList.toggle('open',open);document.querySelector('#cartDrawer').setAttribute('aria-hidden',!open)}
function showToast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
const mapProviders={google:{embed:'https://www.google.com/maps?q=JCX5%2B6HW%20San%20Mart%C3%ADn%20Librer%C3%ADa%20y%20Papeler%C3%ADa%2C%20Cdad.%20de%20Guatemala&output=embed',link:'https://www.google.com/maps/search/?api=1&query=JCX5%2B6HW%20San%20Mart%C3%ADn%20Librer%C3%ADa%20y%20Papeler%C3%ADa%2C%20Cdad.%20de%20Guatemala',label:'Abrir ubicación en Google Maps →'},waze:{embed:'https://embed.waze.com/iframe?zoom=16&lat=14.648101&lon=-90.591137&ct=livemap',link:'https://waze.com/ul?ll=14.648101%2C-90.591137&navigate=yes',label:'Abrir ubicación en Waze →'}};
document.querySelectorAll('[data-map-provider]').forEach(button=>button.addEventListener('click',()=>{const provider=mapProviders[button.dataset.mapProvider],map=document.querySelector('#storeMap'),link=document.querySelector('#mapOpenLink'),wazeLaunch=document.querySelector('#wazeMapLaunch');if(!provider||!map||!link)return;map.src=provider.embed;link.href=provider.link;link.textContent=provider.label;if(wazeLaunch)wazeLaunch.hidden=button.dataset.mapProvider!=='waze';document.querySelectorAll('[data-map-provider]').forEach(item=>item.classList.toggle('active',item===button));}));
