if(hasCatalogPage){document.querySelector('#smartFilters').addEventListener('change',event=>{const input=event.target;if(input.matches('[data-smart-sort]')){filterState.sort=input.value;refreshCatalog();return;}if(input.matches('[data-smart-filter]')){const key=input.dataset.smartFilter,value=input.value;if(key==='categoryId'){filterState.categoryId=value;filterState.subcategories.clear();activeCategory=categoryName(value);}else input.checked?filterState[key].add(value):filterState[key].delete(value);refreshCatalog();return;}if(input.matches('[data-price-bound]')){const value=input.value===''?null:Math.max(0,Number(input.value));filterState[input.dataset.priceBound==='min'?'minPrice':'maxPrice']=Number.isFinite(value)?value:null;if(filterState.minPrice!==null&&filterState.maxPrice!==null&&filterState.minPrice>filterState.maxPrice)filterState.maxPrice=filterState.minPrice;refreshCatalog();}});document.querySelector('#activeFilterChips').addEventListener('click',event=>{const button=event.target.closest('[data-remove-filter]');if(!button)return;const key=button.dataset.removeFilter;if(key==='categoryId'){filterState.categoryId=null;filterState.subcategories.clear();activeCategory='Todos';}else if(key==='price'){filterState.minPrice=null;filterState.maxPrice=null;}else filterState[key].delete(button.dataset.value);refreshCatalog();});document.querySelector('#resetFilters').addEventListener('click',()=>{filterState.sort='';filterState.categoryId=null;filterState.subcategories.clear();filterState.brands.clear();filterState.colors.clear();filterState.pieces.clear();filterState.minPrice=null;filterState.maxPrice=null;activeCategory='Todos';activeBrandSlug='';query='';document.querySelector('#searchInput').value='';refreshCatalog();});}
function toggleFilterSheet(open){if(!hasCatalogPage)return;document.body.classList.toggle('filters-open',open);document.querySelector('#catalogFilters').setAttribute('aria-hidden',String(!open));}
if(hasCatalogPage){document.querySelector('#openFilters').addEventListener('click',()=>toggleFilterSheet(true));document.querySelector('#closeFilters').addEventListener('click',()=>toggleFilterSheet(false));document.querySelector('#filterSheetOverlay').addEventListener('click',()=>toggleFilterSheet(false));document.querySelector('#mobileSort').addEventListener('change',event=>{filterState.sort=event.target.value;refreshCatalog();});}
if(hasCatalogPage){document.querySelectorAll('.catalog-pagination').forEach(nav=>nav.addEventListener('click',event=>{const button=event.target.closest('[data-page]');if(!button||button.disabled)return;currentPage=Number(button.dataset.page);renderProducts();document.querySelector('#productGrid').scrollIntoView({behavior:'smooth',block:'start'});}));}
document.querySelector('#searchButton').addEventListener('click',()=>{query=document.querySelector('#searchInput').value;if(!hasCatalogPage){window.location.href=`catalogo.html?buscar=${encodeURIComponent(query)}`;return;}activeCategory='Todos';currentPage=1;renderFilters();renderProducts();document.querySelector('#catalogo').scrollIntoView()});
document.querySelector('#searchInput').addEventListener('keydown',e=>{if(e.key==='Enter')document.querySelector('#searchButton').click()});
document.querySelector('#cartButton').addEventListener('click',()=>toggleCart(true));document.querySelector('#closeCart').addEventListener('click',()=>toggleCart(false));document.querySelector('#overlay').addEventListener('click',()=>toggleCart(false));
renderCart();
const deliveryCostLabel=document.querySelector('input[name="deliveryMethod"][value="DOMICILIO"]')?.closest('label')?.querySelector('b');if(deliveryCostLabel)deliveryCostLabel.textContent='Q25 · gratis si supera Q200';
document.querySelectorAll('input[name="deliveryMethod"]').forEach(input=>input.addEventListener('change',event=>{selectedDelivery=event.target.value;renderCart()}));
document.querySelectorAll('input[name="paymentMethod"]').forEach(input=>input.addEventListener('change',event=>{selectedPayment=event.target.value;renderCart()}));
document.querySelector('#checkoutButton').addEventListener('click',async()=>{if(!cart.length)return showToast('Tu carrito está vacío.');const totalCarrito=cart.reduce((sum,item)=>sum+Number(item.precio)*item.cantidad,0);if(!selectedDelivery)return showToast('Selecciona si deseas recoger en tienda o envío a domicilio.');const pedidoMinimo=selectedDelivery==='RETIRO_TIENDA'?1:100;if(totalCarrito<pedidoMinimo)return showToast(`El pedido mínimo para ${selectedDelivery==='RETIRO_TIENDA'?'recoger en tienda':'envío a domicilio'} es de ${money(pedidoMinimo)}. Te faltan ${money(pedidoMinimo-totalCarrito)}.`);if(!selectedPayment)return showToast('Selecciona el método de pago.');const {data:{user}}=await supabaseClient.auth.getUser();if(!user){window.location.href=`login.html?returnTo=${encodeURIComponent(window.location.pathname.split('/').pop()||'index.html')}`;return}const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;if(cart.some(item=>!uuid.test(item.producto_id)))return showToast('El checkout estará disponible al conectar el catálogo real de Supabase.');const button=document.querySelector('#checkoutButton');button.disabled=true;button.textContent='Verificando inventario…';const {data,error}=await supabaseClient.rpc('crear_pedido_ecommerce',{p_items:cart.map(item=>({producto_id:item.producto_id,cantidad:item.cantidad})),p_metodo_entrega:selectedDelivery,p_metodo_pago:selectedPayment});button.disabled=false;button.textContent='Confirmar pedido';if(error)return showToast(error.message);cart=[];guardarCarrito();renderCart();toggleCart(false);showToast(`Pedido ${data.numero} creado correctamente.`)});
const newsletterForm=document.querySelector('#newsletter');if(newsletterForm)newsletterForm.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,email=form.querySelector('input[type="email"]')?.value.trim(),button=form.querySelector('button');if(!supabaseClient)return showToast('No pudimos conectar el newsletter. Inténtalo nuevamente.');button.disabled=true;const {error}=await supabaseClient.rpc('suscribir_newsletter',{p_correo:email});button.disabled=false;if(error)return showToast(error.message||'No pudimos registrar tu correo. Inténtalo nuevamente.');form.reset();showToast('¡Listo! Te suscribiste a nuestras novedades.')});
document.querySelector('#menuButton').addEventListener('click',()=>{
  const header=document.querySelector('.site-header');
  const isOpen=header.classList.toggle('menu-open');
  document.querySelector('#menuButton').setAttribute('aria-label',isOpen?'Cerrar menú':'Abrir menú');
});
document.querySelector('#favoritesButton')?.addEventListener('click',()=>{window.location.href='mi-cuenta.html?tab=favoritos'});
function applyCategoryFromUrl(attempt=0){if(!hasCatalogPage)return;const slug=pageParams.get('categoria');if(!slug)return;if(!remoteCategories.length){if(attempt<20)setTimeout(()=>applyCategoryFromUrl(attempt+1),250);return;}const category=remoteCategories.find(item=>item.slug===slug);if(category)selectCategoryFromHeader(category.nombre);}
function applyBrandFromUrl(attempt=0){if(!hasCatalogPage||!activeBrandSlug)return;if(!remoteBrands.length){if(attempt<20)setTimeout(()=>applyBrandFromUrl(attempt+1),250);return;}const brand=remoteBrands.find(item=>item.slug===activeBrandSlug);if(!brand)return;filterState.brands.clear();filterState.brands.add(brand.id);refreshCatalog();}
setTimeout(()=>applyCategoryFromUrl(),300);
setTimeout(()=>applyBrandFromUrl(),350);
document.querySelector('#categoryNav').addEventListener('click',event=>{
  const link=event.target.closest('a');
  if(!link)return;
  event.preventDefault();
  if(link.classList.contains('sale-link')){
    if(!hasCatalogPage){window.location.href='catalogo.html?destacados=1';return;}
    filterState.featured=true;refreshCatalog();return;
  }
  const name=link.dataset.category||'';
  if(!hasCatalogPage){
    const category=remoteCategories.find(item=>item.nombre===name);
    window.location.href=category?.slug?`catalogo.html?categoria=${encodeURIComponent(category.slug)}`:'catalogo.html';
    return;
  }
  selectCategoryFromHeader(name);
  document.querySelector('.site-header').classList.remove('menu-open');
});

function configureFeaturedNavigation(){const link=document.querySelector('#categoryNav .sale-link');if(!link)return;link.href='catalogo.html?destacados=1';link.dataset.featuredNav='true';}
const categoryNav=document.querySelector('#categoryNav');new MutationObserver(configureFeaturedNavigation).observe(categoryNav,{childList:true,subtree:true});configureFeaturedNavigation();

function ensureFeaturedCatalogFilter(){
  if(!hasCatalogPage)return;
  const host=document.querySelector('#smartFilters');
  if(!host||host.querySelector('[data-featured-filter]'))return;
  host.insertAdjacentHTML('beforeend',accordion('Destacados',`<div class="filter-options"><label class="filter-option ${filterState.featured?'is-selected':''}"><input type="checkbox" data-featured-filter ${filterState.featured?'checked':''}><span>Solo productos destacados</span></label></div>`));
}
if(hasCatalogPage){
  const featuredFilterHost=document.querySelector('#smartFilters');
  new MutationObserver(ensureFeaturedCatalogFilter).observe(featuredFilterHost,{childList:true});
  featuredFilterHost.addEventListener('change',event=>{if(!event.target.matches('[data-featured-filter]'))return;filterState.featured=event.target.checked;refreshCatalog();});
  document.querySelector('#resetFilters').addEventListener('click',()=>{if(filterState.featured){filterState.featured=false;refreshCatalog();}});
  ensureFeaturedCatalogFilter();
}

