  aboutLinks.dataset.footerNosotros='true';
  aboutLinks.innerHTML='<strong>Nosotros</strong><a href="nosotros-historia.html">Historia</a><a href="nosotros-perfil.html">Perfil de la empresa</a><a href="nosotros-gobierno-etica.html">Gobierno y ética</a><a href="nosotros-clientes-operacion.html">Clientes y operación</a><a href="nosotros-cadena-suministro.html">Cadena de suministro</a><a href="nosotros-personas.html">Personas</a>';
  const help=Array.from(footerGrid.children).find(section=>section.querySelector(':scope > strong')?.textContent==='Ayuda');
  if(help&&!help.querySelector('a[href="terminos-condiciones.html"]'))help.insertAdjacentHTML('beforeend','<a href="terminos-condiciones.html">Términos y condiciones</a>');
